), resolved as (
  select
    incoming.*,
    universities.id as university_id
  from incoming
  join public.universities on universities.slug = incoming.university_slug
)
insert into public.programmes (
  university_id, university_name, programme_name, country_code, city,
  degree_level, teaching_language, intake, source_url, application_url,
  academic_year, verification_status, verification_notes, requirements,
  catalogue_source_url, catalogue_checked_at, duration_years
)
select
  university_id,
  university_name,
  programme_name,
  'IT',
  city,
  degree_level,
  'English',
  'Fall 2026',
  source_url,
  source_url,
  '2026/27',
  'unverified',
  'Listed on the university''s official English-taught programme page on 3 October 2026. Admission requirements, fees, and deadlines require human verification.',
  '{}'::jsonb,
  catalogue_source_url,
  date '2026-10-03',
  duration_years
from resolved
on conflict (university_name, programme_name, academic_year, degree_level) do nothing;

select private.apply_bulk_programme_defaults();
